def caesar_cipher(text: str, shift: int) -> str:
    if not isinstance(text, str) or not isinstance(shift, int):
        return ""

    result = ""
    for char in text:
        if char.isalpha():
            shift_amount = shift % 26
            if char.islower():
                result += chr((ord(char) - ord('a') + shift_amount) % 26 + ord('a'))
            else:
                result += chr((ord(char) - ord('A') + shift_amount) % 26 + ord('A'))
        else:
            result += char

    return result

